<template>
  <div class="settings-screen">
    <h2>Выберите сложность</h2>
    <button @click="setDifficulty('easy')">Легкая 8x8, 10 мин</button>
    <button @click="setDifficulty('medium')">Средняя 16x16, 40 мин</button>
    <button @click="setDifficulty('hard')">Сложная 32x16, 100 мин</button>
  </div>
</template>

<script>
export default {
  methods: {
    setDifficulty(level) {
      this.$store.commit('setDifficulty', level);
      this.$router.push('/game');
    }
  }
};
</script>

<style>
.settings-screen {
  text-align: center;
}

.settings-screen button {
  margin: 10px;
}
</style>